# ===== stores/counter.js =====

import { defineStore } from 'pinia'

# ===== 方式1: Option Store =====
export const useCounterStore = defineStore('counter', {
  state: () => ({
    count: 0,
    name: '计数器'
  }),
  getters: {
    doubleCount: (state) => state.count * 2
  },
  actions: {
    increment() {
      this.count++
    }
  }
})

# ===== 方式2: Setup Store（推荐）=====
import { ref, computed } from 'vue'

export const useCounterStore = defineStore('counter', () => {
  const count = ref(0)
  const doubleCount = computed(() => count.value * 2)

  function increment() {
    count.value++
  }

  # 必须 return！不 return 的不暴露
  return { count, doubleCount, increment }
})


💡 推荐 Setup Store——和 Vue3 Composable 风格一致
💡 约定：useXxxStore 命名

# ===== stores/user.js —— 完整示例 =====

import { defineStore } from 'pinia'

export const useUserStore = defineStore('user', {
  state: () => ({
    name: '张三',
    age: 25,
    loggedIn: false
  }),

  getters: {
    upperName: (state) => state.name.toUpperCase(),
    isAdult: (state) => state.age >= 18,
    # 访问其他 getter
    greeting: (state) => {
      return state.age >= 18 ? '您好' : '小朋友好'
    }
  }
})


# ===== 组件中使用 =====
<script setup>
import { useUserStore } from '@/stores/user'
const user = useUserStore()

// 直接读写 state
user.name = '李四'
user.age++

// 批量更新（性能更好）
user.$patch({ name: '王五', age: 30 })

// 重置
user.$reset()  # name → 张三, age → 25
</script>


💡 state 是响应式的，改了自动更新 UI
💡 $patch 批量更新性能优于多次赋值
💡 $reset 恢复到初始值

# ===== stores/todo.js —— Actions 异步示例 =====

import { defineStore } from 'pinia'

export const useTodoStore = defineStore('todo', {
  state: () => ({
    list: [],
    loading: false
  }),

  getters: {
    doneCount: (state) =>
      state.list.filter(t => t.done).length
  },

  actions: {
    // 同步 Action
    addItem(text) {
      this.list.push({
        id: Date.now(),
        text,
        done: false
      })
    },

    removeItem(id) {
      this.list = this.list.filter(t => t.id !== id)
    },

    toggleItem(id) {
      const item = this.list.find(t => t.id === id)
      if (item) item.done = !item.done
    },

    // 异步 Action（调 API）
    async fetchTodos() {
      this.loading = true
      try {
        const res = await fetch('/api/todos')
        this.list = await res.json()
      } finally {
        this.loading = false
      }
    }
  }
})


💡 Actions 里可以 async/await
💡 用 this 访问 state 和其他 actions
💡 不需要 mutations——直接改 state！

# ===== $subscribe 持久化 =====

import { useCounterStore } from '@/stores/counter'

const store = useCounterStore()

// $subscribe 监听变化
store.$subscribe((mutation, state) => {
  // mutation.type: 'direct' | 'patch object' | 'patch function'
  console.log('state 变了:', mutation.type)

  // 自动保存到 localStorage
  localStorage.setItem(
    'counter-state',
    JSON.stringify(state)
  )
})


# ===== $onAction 日志 =====

store.$onAction(({ name, args, after, onError }) => {
  console.log(`Action ${name} 开始`, args)

  after((result) => {
    console.log(`Action ${name} 完成`)
  })

  onError((error) => {
    console.error(`Action ${name} 失败:`, error)
  })
})


💡 $subscribe → 持久化、同步
💡 $onAction   → 日志、埋点
💡 刷新页面 → state 从 localStorage 恢复

# ===== stores/cart.js =====

import { defineStore } from 'pinia'

export const useCartStore = defineStore('cart', {
  state: () => ({
    items: [
      { id: 1, name: 'Vue3 教程', price: 99, qty: 1 },
      { id: 2, name: 'Pinia 指南', price: 79, qty: 2 }
    ]
  }),

  getters: {
    total: (state) =>
      state.items.reduce((s, i) => s + i.price * i.qty, 0),
    count: (state) =>
      state.items.reduce((s, i) => s + i.qty, 0)
  },

  actions: {
    addItem(item) {
      const exist = this.items.find(i => i.id === item.id)
      if (exist) {
        exist.qty += item.qty || 1
      } else {
        this.items.push({ ...item, qty: item.qty || 1 })
      }
    },
    updateQty(id, qty) {
      const item = this.items.find(i => i.id === id)
      if (item) item.qty = qty
    },
    removeItem(id) {
      this.items = this.items.filter(i => i.id !== id)
    },
    clear() {
      this.items = []
    }
  }
})


# ===== 组件中使用 =====
